with with_gaps as (select *, case when lag(started_at) over (partition by customer_id order by started_at asc, id asc) is null or started_at > lag(started_at) over (partition by customer_id order by started_at asc, id asc) + interval 90 days then 1 else 0 end as is_new_session from sessions), sessionized as (select id, customer_id, browser, started_at, sum(is_new_session) over (partition by customer_id order by started_at asc, id asc rows between unbounded preceding and current row) as island_id from with_gaps) select id, browser from sessionized order by browser asc nulls last, id desc
